PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "kysely_migration" ("name" varchar(255) not null primary key, "timestamp" varchar(255) not null);
CREATE TABLE IF NOT EXISTS "kysely_migration_lock" ("id" varchar(255) not null primary key, "is_locked" integer default 0 not null);
CREATE TABLE IF NOT EXISTS "revisions" ("id" text primary key, "page_id" text not null references "pages" ("id") on delete cascade, "content" text not null, "created_at" text not null, "kind" text default 'published' not null, "created_by" text);
CREATE TABLE IF NOT EXISTS "settings" ("key" text primary key, "value" text not null, "updated_by" text);
CREATE TABLE IF NOT EXISTS "jobs" ("id" text primary key, "kind" text not null, "payload" text not null, "status" text not null, "error" text, "attempts" integer default 0 not null, "created_at" text not null, "finished_at" text, "result" text, "run_at" text, "log" text, "created_by" text);
CREATE TABLE IF NOT EXISTS "pages" ("id" text primary key, "parent_id" text references "pages" ("id"), "slug" text not null, "position" integer not null, "draft" text not null, "published_revision_id" text, "created_at" text not null, "updated_at" text not null, "deleted_at" text, "template" text, "kind" text default 'page' not null, "listing" text, "publish_at" text, "updated_by" text);
CREATE TABLE IF NOT EXISTS "redirects" ("id" text primary key, "source_path" text not null unique, "target_page_id" text references "pages" ("id") on delete cascade, "target_url" text, "status" integer not null, "page_id" text references "pages" ("id") on delete set null, "created_at" text not null);
CREATE TABLE IF NOT EXISTS "media" ("id" text primary key, "filename" text not null, "type" text not null, "ext" text not null, "size" integer not null, "width" integer, "height" integer, "alt" text default '' not null, "caption" text default '' not null, "credit" text default '' not null, "variants" text default '[]' not null, "variants_size" integer default 0 not null, "status" text not null, "created_at" text not null, "updated_at" text not null, "deleted_at" text, "decorative" integer default 0 not null, "replaced_at" text, "previous" text, "created_by" text);
CREATE TABLE IF NOT EXISTS "media_usage" ("media_id" text not null references "media" ("id") on delete cascade, "owner" text not null, constraint "media_usage_pk" primary key ("media_id", "owner"));
CREATE TABLE IF NOT EXISTS "users" ("id" text primary key, "username" text not null unique, "display_name" text not null, "role" text not null, "password_hash" text not null, "must_change_password" integer default 0 not null, "totp_secret" text, "totp_last_step" integer, "totp_enrolled_at" text, "preferences" text default '{"language":"en"}' not null, "disabled_at" text, "last_sign_in_at" text, "created_at" text not null, "created_by" text);
CREATE TABLE IF NOT EXISTS "sessions" ("id" text primary key, "token_hash" text not null unique, "user_id" text not null references "users" ("id") on delete cascade, "stage" text not null, "created_at" text not null, "last_seen_at" text not null, "ip" text default '' not null, "user_agent" text default '' not null);
CREATE TABLE IF NOT EXISTS "tokens" ("id" text primary key, "token_hash" text not null unique, "kind" text not null, "role" text, "user_id" text references "users" ("id") on delete cascade, "note" text default '' not null, "created_by" text, "created_at" text not null, "expires_at" text not null, "used_at" text);
CREATE TABLE IF NOT EXISTS "recovery_codes" ("user_id" text not null references "users" ("id") on delete cascade, "code_hash" text not null, "used_at" text, constraint "recovery_codes_pk" primary key ("user_id", "code_hash"));
CREATE TABLE IF NOT EXISTS "audit_log" ("id" integer primary key autoincrement, "at" text not null, "user_id" text, "action" text not null, "target" text, "detail" text default '{}' not null, "ip" text);
DELETE FROM sqlite_sequence;
CREATE INDEX "revisions_page_id" on "revisions" ("page_id");
CREATE INDEX "jobs_status" on "jobs" ("status", "created_at");
CREATE INDEX "pages_parent_id" on "pages" ("parent_id");
CREATE INDEX "media_usage_owner" on "media_usage" ("owner");
CREATE INDEX "jobs_run_at" on "jobs" ("status", "run_at");
CREATE INDEX "revisions_page_created" on "revisions" ("page_id", "created_at");
CREATE INDEX "pages_listing_publish_at" on "pages" ("parent_id", "kind", "publish_at");
CREATE INDEX "sessions_user" on "sessions" ("user_id");
CREATE INDEX "audit_log_at" on "audit_log" ("at");
CREATE INDEX "audit_log_user" on "audit_log" ("user_id", "id");
CREATE INDEX "audit_log_action" on "audit_log" ("action", "id");
CREATE UNIQUE INDEX pages_sibling_slug on pages (coalesce(parent_id, ''), slug)
        where deleted_at is null;
COMMIT;
